pub fn isIsolatedLinker(load_result: Lockfile.LoadResult, configured: install.PackageManager.Options.NodeLinker) bool {
        if ((configured == .isolated)) {
            return true;
        }
        if ((configured == .hoisted)) {
            return false;
        }
        switch (load_result) {
.ok => |ok| {
return ((ok.lockfile.saved_config_version != null) and (ok.lockfile.saved_config_version.? == .v1));
},
else => {
return false;
},
}
}

pub fn licenseOrder(a: []const u8, b: []const u8) std.math.Order {
        const a_unk = strings.eqlComptime(a, UNKNOWN_LICENSE);
        const b_unk = strings.eqlComptime(b, UNKNOWN_LICENSE);
        if ((a_unk != b_unk)) {
            return (if (a_unk) .gt else .lt);
        }
        const a_key = (if (((a.len > 0) and (a[0] == 40))) a[1..] else a);
