        var out = std.array_list.Managed(u8).init(allocator);
        _ = &out;
        defer {
        _ = out.deinit();
        }
        const w = (&out);
        if ((entries.len == 0)) {
            _ = try Output.writer().writeAll("{}\n");
            return;
        }
        _ = try out.appendSlice("{\n");
        var start: usize = 0;
        _ = &start;
        while ((start < entries.len)) {
            const license = entries[@as(usize, @intCast(start))].license;
            var end = (start + 1);
            _ = &end;
            while (((end < entries.len) and strings.eql(entries[@as(usize, @intCast(end))].license, license))) {
                end = (end + 1);
            }
            if ((start > 0)) {
                _ = try out.appendSlice(",\n");
            }
            _ = try out.appendSlice("  ");
            _ = try jsonString(w, license);
            _ = try out.appendSlice(": [");
            var group_start = start;
            _ = &group_start;
            var first_group = true;
            _ = &first_group;
            while ((group_start < end)) {
                const first = entries[@as(usize, @intCast(group_start))];
                var group_end = (group_start + 1);
                _ = &group_end;
                while (((group_end < end) and strings.eql((if (@typeInfo(@TypeOf(entries[@as(usize, @intCast(group_end))])) == .@"enum" or @typeInfo(@TypeOf(entries[@as(usize, @intCast(group_end))])) == .@"union") @tagName(entries[@as(usize, @intCast(group_end))]) else entries[@as(usize, @intCast(group_end))].name), (if (@typeInfo(@TypeOf(first)) == .@"enum" or @typeInfo(@TypeOf(first)) == .@"union") @tagName(first) else first.name)))) {
                    group_end = (group_end + 1);
                }
                if ((!first_group)) {
                    _ = try out.append(44);
                }
                first_group = false;
                _ = try out.appendSlice("\n    {\n      \"name\": ");
                _ = try jsonString(w, (if (@typeInfo(@TypeOf(first)) == .@"enum" or @typeInfo(@TypeOf(first)) == .@"union") @tagName(first) else first.name));
                var kept = std.array_list.Managed(usize).init(allocator);
                _ = &kept;
                defer {
                _ = kept.deinit();
                }
                var gi = group_start;
                _ = &gi;
                while ((gi < group_end)) : (gi = (gi + 1)) {
                    if (((kept.items.len == 0) or (!strings.eql(entries[@as(usize, @intCast(kept.items[@as(usize, @intCast((kept.items.len - 1)))]))].version, entries[@as(usize, @intCast(gi))].version)))) {
                        _ = try kept.append(gi);
                    }
                }
                _ = try out.appendSlice(",\n      \"versions\": [");
                var ki: usize = 0;
                _ = &ki;
                while ((ki < kept.items.len)) : (ki = (ki + 1)) {
                    if ((ki > 0)) {
                        _ = try out.appendSlice(", ");
                    }
                    _ = try jsonString(w, entries[@as(usize, @intCast(kept.items[@as(usize, @intCast(ki))]))].version);
                }
                _ = try out.appendSlice("],\n      \"paths\": [");
                ki = 0;
                while ((ki < kept.items.len)) : (ki = (ki + 1)) {
                    if ((ki > 0)) {
                        _ = try out.appendSlice(", ");
                    }
                    _ = try jsonString(w, entries[@as(usize, @intCast(kept.items[@as(usize, @intCast(ki))]))].path);
                }
                _ = try out.appendSlice("],\n      \"license\": ");
                _ = try jsonString(w, license);
                const newest = entries[@as(usize, @intCast((group_end - 1)))];
                const extra_keys: [3][]const u8 = .{ "author", "description", "homepage" };
                const extra_vals: [3]?[]u8 = .{ newest.author, newest.description, newest.homepage };
                var ei: usize = 0;
                _ = &ei;
                while ((ei < 3)) : (ei = (ei + 1)) {
                    if (extra_vals[@as(usize, @intCast(ei))]) |val| {
                        _ = &val;
                        _ = try out.appendSlice(",\n      \"");
                        _ = try out.appendSlice(extra_keys[@as(usize, @intCast(ei))]);
                        _ = try out.appendSlice("\": ");
                        _ = try jsonString(w, val);
                    }
                }
                _ = try out.appendSlice("\n    }");
                group_start = group_end;
            }
            _ = try out.appendSlice("\n  ]");
            start = end;
        }
        _ = try out.appendSlice("\n}\n");
        _ = try Output.writer().writeAll(out.items);
}
